-- The control for `update_index_size_before_later_unique_loud`: the unique index created
-- first, its `23505` comes first.
-- @setup
CREATE TABLE t (id int, a text, u int);
CREATE UNIQUE INDEX t_u ON t (u);
CREATE INDEX t_a ON t (a);
INSERT INTO t VALUES (1, 'x', 1), (2, 'y', 2);
-- @test
-- @expect-error: the first index's duplicate before the second's size
-- @expect-message
-- @profile-lock
UPDATE t SET a = '', u = 1 WHERE id = 2;
